WITH base AS (SELECT *, ROUND(unit_price / quantity, 2) AS line_total FROM order_items WHERE product_id IN (8, 9, 14)) SELECT CASE WHEN line_total >= 80 THEN 'HIGH' ELSE 'LOW' END AS line_total_tier, order_id, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, COUNT(DISTINCT order_id) AS distinct_order_ids, AVG(quantity) AS avg_quantity, PERCENTILE_APPROX(unit_price, 0.95) AS unit_price_p95, APPROX_PERCENTILE(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles_2 FROM base GROUP BY line_total_tier, order_id ORDER BY unit_price_p95 DESC;
